mapper.select:
SELECT id, template_id, type, branch_id, data, created_time
FROM sp_template_data
WHERE id = #{id}

SELECT row_to_json(t)::jsonb as result
FROM (
    SELECT data
    FROM sp_template_data
    WHERE template_id = #{templateId} AND type = #{type}

        AND branch_id = #{branchId}

    ORDER BY created_time DESC
    LIMIT 1
) t

SELECT id, template_id, type, branch_id, data, created_time
FROM sp_template_data
WHERE template_id = #{templateId} AND type = #{type}

    AND branch_id = #{branchId}

ORDER BY created_time DESC
LIMIT 1

